// Client share links. Creation goes through the create_album_share RPC
// (SECURITY INVOKER, so RLS applies); anonymous viewing goes through the
// get_shared_album RPC only. The token is generated by the database.

import { supabase } from "@/integrations/supabase/client";
import type { Json } from "@/integrations/supabase/types";

export type ShareMode = "album" | "favorites" | "selection";
export type ShareExpiry = "7" | "30" | "never";

export interface AlbumShare {
  id: string;
  album_id: string;
  created_by: string;
  token: string;
  mode: ShareMode;
  allow_download: boolean;
  expires_at: string | null;
  revoked_at: string | null;
  created_at: string;
  photo_count: number | null; // null for whole-album links (live count)
}

export interface CreateShareInput {
  albumId: string;
  mode: ShareMode;
  photoIds?: string[];
  expiry: ShareExpiry;
  allowDownload: boolean;
}

export interface CreatedShare {
  id: string;
  token: string;
  expires_at: string | null;
  photo_count: number;
}

export function shareUrl(token: string): string {
  return `${window.location.origin}/s/${token}`;
}

export type ShareStatus = "active" | "expired" | "revoked";

export function shareStatus(share: Pick<AlbumShare, "expires_at" | "revoked_at">, now = Date.now()): ShareStatus {
  if (share.revoked_at) return "revoked";
  if (share.expires_at && new Date(share.expires_at).getTime() <= now) return "expired";
  return "active";
}

export const SHARE_MODE_LABEL: Record<ShareMode, string> = {
  album: "Whole album",
  favorites: "Favorites",
  selection: "Selected photos",
};

export async function createShare(input: CreateShareInput): Promise<CreatedShare> {
  const { data, error } = await supabase.rpc("create_album_share", {
    p_album_id: input.albumId,
    p_mode: input.mode,
    p_photo_ids: input.mode === "selection" ? input.photoIds ?? [] : null,
    p_expires_in_days: input.expiry === "never" ? null : Number(input.expiry),
    p_allow_download: input.allowDownload,
  });
  if (error) throw error;
  const row = Array.isArray(data) ? data[0] : null;
  if (!row) throw new Error("The link could not be created.");
  return row;
}

/** Share links for one album (client: their own; admin: everyone's). */
export async function listShares(albumId: string): Promise<AlbumShare[]> {
  const { data, error } = await supabase
    .from("album_shares")
    .select("id, album_id, created_by, token, mode, allow_download, expires_at, revoked_at, created_at, album_share_photos(count)")
    .eq("album_id", albumId)
    .order("created_at", { ascending: false });
  if (error) throw error;
  return (data || []).map((row) => {
    const counts = row.album_share_photos as unknown as Array<{ count: number }> | null;
    return {
      id: row.id,
      album_id: row.album_id,
      created_by: row.created_by,
      token: row.token,
      mode: row.mode as ShareMode,
      allow_download: row.allow_download,
      expires_at: row.expires_at,
      revoked_at: row.revoked_at,
      created_at: row.created_at,
      photo_count: row.mode === "album" ? null : counts?.[0]?.count ?? 0,
    };
  });
}

/** Count of currently-active links for an album (admin album cards). */
export async function countActiveShares(albumId: string): Promise<number> {
  const nowIso = new Date().toISOString();
  const { count, error } = await supabase
    .from("album_shares")
    .select("id", { count: "exact", head: true })
    .eq("album_id", albumId)
    .is("revoked_at", null)
    .or(`expires_at.is.null,expires_at.gt.${nowIso}`);
  if (error) throw error;
  return count ?? 0;
}

export async function revokeShare(shareId: string): Promise<void> {
  // The database stamps the real revoke time + who revoked it.
  const { error } = await supabase
    .from("album_shares")
    .update({ revoked_at: new Date().toISOString() })
    .eq("id", shareId);
  if (error) throw error;
}

// ---- Public (anonymous) view -------------------------------------------------

export interface SharedPhoto {
  id: string;
  thumbnail_url: string | null;
  preview_url: string | null;
  url: string | null; // only present when the link allows downloads
  original_filename?: string | null; // present once the share RPC includes it
  width: number | null;
  height: number | null;
}

export type SharedAlbumResult =
  | {
      status: "ok";
      album_title: string;
      mode: ShareMode;
      allow_download: boolean;
      expires_at: string | null;
      photos: SharedPhoto[];
    }
  | { status: "not_found" | "expired" | "revoked" };

export async function fetchSharedAlbum(token: string): Promise<SharedAlbumResult> {
  const { data, error } = await supabase.rpc("get_shared_album", { p_token: token });
  if (error) throw error;
  const result = data as Json as unknown as SharedAlbumResult | null;
  if (!result || typeof result !== "object" || !("status" in result)) {
    return { status: "not_found" };
  }
  return result;
}

export function formatShareDate(iso: string): string {
  return new Date(iso).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}
